-- ---- development credentials (open question 1): username = email,
-- password "Hrms#2026" (bcrypt cost 10) for every seeded employee. DEV ONLY.
SELECT emp_id, lower(email), '$2a$10$uSAWqbe128UMRi6JonMBqeZMlmE8E8G8GWEodK5og.wc6Gyp0LcAW', now(), 'SYSTEM'
FROM employees WHERE email IS NOT NULL;

-- ---- current-year balances for accrual leave types (legacy seeded none) ----
SELECT e.emp_id, lt.leave_type_id, 2026, 0, round(lt.accrual_rate * 10, 2), 'SYSTEM'
FROM employees e CROSS JOIN leave_types lt
WHERE e.employment_status = 'ACTIVE' AND lt.accrual_flag = 'Y';
